import sys
from collections import defaultdict

def count_subsequences(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = 1
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[m][n]

def find_subsequence(s):
    n = len(s)
    freq = defaultdict(int)
    for i in range(1, 1 << n):
        subseq = ''.join(s[j] for j in range(n) if i & (1 << j))
        freq[subseq] += 1
    for subseq in freq:
        if freq[subseq] == 2:
            return subseq
    return '-1'

def main():
    import sys
    input = sys.stdin.read().split()
    T = int(input[0])
    results = []
    index = 1
    for _ in range(T):
        S = input[index]
        results.append(find_subsequence(S))
        index += 1
    for result in results:
        print(result)

main()
